use std::io::{self,BufRead,Write}; const KEY:u8=0xAD;
fn hv(c:u8)->Option<u8>{match c{b'0'..=b'9'=>Some(c-b'0'),b'a'..=b'f'=>Some(c-b'a'+10),b'A'..=b'F'=>Some(c-b'A'+10),_=>None}}
fn main(){let stdin=io::stdin();let mut out=io::BufWriter::new(io::stdout());for l in stdin.lock().lines(){let s=l.unwrap();if s=="PING"{writeln!(out,"PONG").unwrap();out.flush().unwrap();continue}if s=="QUIT"{break}let b=s.as_bytes();if b.len()>=2&&(b[0]==b'E'||b[0]==b'D')&&b[1]==b' '{let h=&b[2..];if h.len()%2!=0{writeln!(out,"ERR").unwrap();out.flush().unwrap();continue}let mut ok=true;for i in (0..h.len()).step_by(2){if let(Some(a),Some(z))=(hv(h[i]),hv(h[i+1])){write!(out,"{:02x}",((a<<4)|z)^KEY).unwrap()}else{ok=false;break}}if ok{writeln!(out).unwrap()}else{writeln!(out,"ERR").unwrap()}out.flush().unwrap()}else{writeln!(out,"ERR").unwrap();out.flush().unwrap()}}}
